local OverseaManageMenuSettingNode = Class('OverseaManageMenuSettingNode')
local MenuCount = 3  ---套餐数量 最多3个套餐

function OverseaManageMenuSettingNode:__init()
end

function OverseaManageMenuSettingNode:__delete()
    if self.managerEvent then
        Events.RemoveListener("MaidCoffeeRefreshManagerStatus",self.managerEvent)
        self.managerEvent = nil
    end

    if self.addBtnEvent then
        Events.RemoveListener("MaidCoffeeRefreshManagerAddStatus",self.addBtnEvent)
        self.addBtnEvent = nil
    end
end

function OverseaManageMenuSettingNode:Awake()
    self:SetGoToStatus(false)
    KTool.SetActive(self.Manager,false)
    KTool.SetActive(self.Manager2.gameObject,false)
    self.managerEvent = Bind(self,self.RefreshManagerStatus)
    Events.AddListener("MaidCoffeeRefreshManagerStatus",self.managerEvent)
    self.addBtnEvent = Bind(self,self.RefreshAddBtnStatus)
    Events.AddListener("MaidCoffeeRefreshManagerAddStatus",self.addBtnEvent)
end

function OverseaManageMenuSettingNode:Start()
    --self:RefreshShowInfo()
end

function OverseaManageMenuSettingNode:SetGoToStatus(status)
    KTool.SetActive(self.GoSettingGroup.gameObject,status)
end

function OverseaManageMenuSettingNode:RefreshRedPoint()
    GameUtils.BindRedPoint(Constants.RedPointConst.MaidCafeMenuSell, self.GoSettingGroup ,true)
end

function OverseaManageMenuSettingNode:SetMenuNoteStatus(status)
    KTool.SetActive(self.BtnTV.gameObject,status)
end

function OverseaManageMenuSettingNode:RefreshShowInfo()
    self:SetTimeAndOrder()
end

function OverseaManageMenuSettingNode:SetActivityTimeShow(time)
    CfUtils.FillText(self.ActivityRemainTime, localize("剩余活动时间：_time_",{_time_ = CfUtils.GetTimeHMS10(checkNumber(time))}))
end

function OverseaManageMenuSettingNode:SetTimeAndOrder()
    ---@type MaidCoffeeComponent
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    ---有多个套装
    local isHaveMenuSell = component:IsHaveMenuSell()
    KTool.SetActive(self.SaleGroup.gameObject,isHaveMenuSell)

    KTool.SetActive(self.Image.gameObject, isHaveMenuSell)
    KTool.SetActive(self.ImgbgSellout.gameObject, not isHaveMenuSell)

    local homeDojo = component:GetMaidCoffeeHomeDoJo()
    local isInActivity = homeDojo:IsActivity()
    KTool.SetActive(self.UIFX_GoldEffect.gameObject,isInActivity)
    KTool.SetActive(self.RemainingTime.gameObject, isInActivity)
    KTool.SetActive(self.UPGroup.gameObject,isInActivity)
    self:RemoveTimer()
    local aniName = isHaveMenuSell and "OverseaManageFoodNode_UPSellBottom" or "OverseaManageFoodNode_UPSellTop"
    CfUtils.PlayAnimation(self.BtnTV,aniName)

    if isInActivity then
        local time = homeDojo:GetActivityLeaveTime()
        if time > 0 then
            self:SetActivityTimeShow(checkNumber(time))
            self.activityTimer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count, id)
                if count > 0 then
                    time = time - 1
                    self:SetActivityTimeShow(checkNumber(time))
                else
                    CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.activityTimer)
                    self.activityTimer = nil
                    KTool.SetActive(self.RemainingTime.gameObject,false)
                end
            end, time + 1, false, true)
        end
    end

    if isHaveMenuSell then
        self:SetMenuShow()
        ---要拿到剩余时间最多的套餐  然后显示
        local remainTimeMax = component:GetRemainTimeMax()
        self.TxtTime.text = CfUtils.GetTimeHMS(checkNumber(remainTimeMax))
        self.Timer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count, id)
            if count > 0 then
                remainTimeMax = remainTimeMax - 1
                self.TxtTime.text = CfUtils.GetTimeHMS(checkNumber(remainTimeMax))
            else
                self.TxtTime.text = CfUtils.GetTimeHMS(checkNumber(remainTimeMax))
                CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
                self.Timer = nil
                ---重新刷新一下UI显示
                self:SetTimeAndOrder()
            end
        end, remainTimeMax + 1, false, true)
    end
end

function OverseaManageMenuSettingNode:SetMenuShow()
    ---@type MaidCoffeeComponent
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    for i = 1, MenuCount do
        local _, isLock = component:GetIsLockedAndVolume(i)
        local ImgCafe = self["ImgCafe"..i]
        if ImgCafe then
            if isLock then
                ImgCafe.Status = 3
            else
                ---判断当前套装是否在售卖中
                local isSell = component:GetCurMenuIsSell(i)
                ImgCafe.Status = isSell and 1 or 2
            end
        end
    end
end

function OverseaManageMenuSettingNode:RefreshManagerShow()
    local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local staffInfo = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Manager ,1)
    local isHaveOwner = (tonumber(staffInfo) ~= 0)
    KTool.SetActive(self.Manager,not isHaveOwner)
end

function OverseaManageMenuSettingNode:RefreshManagerStatus(status)
    KTool.SetActive(self.Manager,status)
end

function OverseaManageMenuSettingNode:RefreshAddBtnStatus(status)
    local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local staffInfo = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Manager ,1)
    local isHaveOwner = (tonumber(staffInfo) ~= 0)
    if isHaveOwner then
        KTool.SetActive(self.Manager2.gameObject,false)
    else
        KTool.SetActive(self.Manager2.gameObject,status)
    end
end

function OverseaManageMenuSettingNode:RemoveTimer()
    if self.Timer then
        CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
        self.Timer = nil
    end

    if self.activityTimer then
        CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.activityTimer)
        self.activityTimer = nil
    end
end

function OverseaManageMenuSettingNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.MaidCafeMenuSell)
    self:RemoveTimer()
    self:Delete()
end

return OverseaManageMenuSettingNode